import csv
import io
import json

thresholds = {}
for line in INPUT_ARTIFACTS["data/thresholds.conf"].splitlines():
    if line:
        key, value = line.split("=", 1)
        thresholds[key] = float(value) if key == "error_rate_warn" else int(value)

rows = csv.DictReader(io.StringIO(INPUT_ARTIFACTS["data/requests.csv"]))
aggregate = {}
for row in rows:
    service = row["service"]
    current = aggregate.setdefault(service, {"requests": 0, "errors": 0})
    current["requests"] += int(row["requests"])
    current["errors"] += int(row["errors"])

warn = thresholds["error_rate_warn"]
result = sorted(
    service
    for service, values in aggregate.items()
    if values["errors"] / values["requests"] > warn
)
print(json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":")))
